out(CONTROL, 4);
}
break;
case E_ABIERTO:
if (boton_p) {
estado = E_BAJANDO;
out(CONTROL, 6);
}
break;
case E_DETENER_S:
if (tics >= T_NSEG) {
estado = E_BAJANDO;
out(CONTROL, 6);
}
break;
case E_DETENER_B:
if (tics >= T_NSEG) {
estado = E_SUBIENDO;
out(CONTROL, 4);
}
break;
case E_SUBIENDO_P:
if (tics >= T_MSEG) {
estado = E_SUBIENDO;
out(CONTROL, 4);
} else if (p_estado & 8) { // sensor de persona
tics = 0;
}
break;
case E_BAJANDO_P:
if (tics >= T_MSEG) {
estado = E_BAJANDO;
out(CONTROL, 6);
} else if (p_estado & 8) { // sensor de persona
tics = 0;
}
break;
} // case
} // while
}
