short isPalindrome(char *str, short izq, short der) {
short result;
if (izq > der) result = true;
else if (str[izq] != str[der]) result = false ;
else result = isPalindrome(str, izq+1, der-1);
return result
}
isPalindome proc
pop AX ; IP
pop SI ; DER
pop DI ; IZQ
pop BX ; str
push AX
cmp DI, SI
jg isTrue
mov CL, [BX+DI]
cmp CL, [BX+SI]
jne isFalse
push BX
inc DI
push DI
dec SI
push SI
call isPalindrome
pop BX
jmp fin
isTrue:
mov BX,1
jmp fin
isFalse:
xor BX, BX
fin:
pop AX
push BX
push AX
ret
isPalindome endp

b)
Para un string de largo n se generan en el peor caso (cuando es palíndromo) techo(n/2) llamadas a la
función.
La función retira los parámetros de entrada al inicio, no preserva contexto y acumula únicamente la dirección de retorno (IP) en las llamadas recursivas. El caso base acumula los parámetros de entrada y el
IP. Entonces en el peor caso para un string de largo n se consume a lo sumo 2*techo(n/2)+8 bytes.
El string tiene un desplazamiento inicial de 0x9000 por lo que el string más largo que puede almacenarse en el segmento (DS) es 0x7000 caracteres. En este caso el consumo máximo será de 0x7008 bytes
que puede almacenarse en el segmento de stack (SS).
Solución alternativa:
a)
isPalindrome proc
push bp
mov bp, sp
push ax
push bx
push cx
push di
push si
mov bx, [bp+8] ; cargar puntero str
mov si, [bp+6] ; cargar izq
mov di, [bp+4] ; cargar der
; Comparar caracteres en índices izq y der
cmp si, di
jae ret_uno ; si izq >= der, devuelve 1
mov al, [bx+si] ; cargar caracter en posición izq
mov cl, [bx+di] ; cargar caracter en posición der
cmp al, cl
jne ret_cero ; si no son iguales, devuelve 0
; llamar a la función recursivamente
inc si
dec di
push bx
push si
push di
call isPalindrome
pop ax
jmp cleanup

ret_cero:
mov ax, 0 ; la cadena no es palíndrome
jmp cleanup
ret_uno:
mov ax, 1 ; la cadena es palíndrome
cleanup:
mov [bp+8], ax ; cargo el resultado en el stack
mov bx, [bp+2] ; guardo el ip
mov [bp+6], bx ; cargo el ip arriba del resultado
pop si
pop di
pop cx
pop bx
pop ax
pop bp
add sp, 4 ; ajusto el sp para que apunte al ip
ret
isPalindrome endp
b)
El consumo de stack en cada llamada es es de 4 palabras por el llamado (3 argumentos y la dirección
de retorno) y 6 palabras por el contexto salvado. Esto vale tanto para la llamada inicial y el paso base,
como para las llamadas recursivas.
Tendremos entonces que en el caso de un texto palíndromo de n caracteres, se realizarán techo(n/2)
llamadas y el paso base, cada una consumiento 10 palabras = 20 bytes.
Dado que tenemos 64KB en cada segmento se deberá cumplir que:
(techo(n/2) + 1) * 20 bytes <= 65536 bytes
por lo que n deberá cumplir:
n < 6552
Por otro lado tenemos la restricción de la cantidad de bytes disponible en el DS para alojar el string, que
ascienden a 0x10000 – 0x9000 = 0x7000 = 28762
En este caso vemos que es más restrictivo el consumo de stack y por tanto el máximo n es 6551.

