ROM[i] = (num + 0x2000) & 0x3FFF;
break;
case 1:
// complemento a 1
ROM[i] = (~num) & 0x3FFF;
break;
case 2:
// complemento a 2
ROM[i] = (-num) & 0x3FFF;
break;
case 3:
// desplazamiento. Un algoritmo para calcular el opuesto es el
// siguiente (todas operaciones de C, en complemento a 2):
// r = num – desp (desplazamiento a complemento a 2)
// r = r * -1 (cálculo de opuesto en complemento a 2)
// r = r + desp (se convierte el opuesto a desplazamiento)
// simplificando, queda como a continuación:
ROM[i] = desp - (num - desp);
break;
}
}
}
