short ROM[...];
void cargaRom(){
int tope = 1 << 18;
for (int i = 0; i < tope; i++){
char op = i >> 16;
char a = i >> 8;
char b = i;
unsigned char b_int = i;
char res = 0;
if (op == 0){
res = a + b;
}else if (op == 1){
res = a - b;
}else if (op == 2){
res = a << b_int;
}else if (op == 3){
res = a >> b_int;
}
char z = (res == 0? 1 : 0) ;
char n = (res < 0? 1 : 0);
ROM[i] = z << 9 | n << 8 | res;
}
}

