char ROM[65536];
void cargarROM (){
//recorro todas las direcciones
for (unsigned int dir = 0; dir < 65536; dir++){
//extraigo los dos operandos y los signos
char op_A = dir >> 8; // operando en v.a y signo.
char op_B = dir & 0xFF; // operando en complemento a 1
char sg_A = op_A >> 7;
char sg_B = op_B >> 7;
if (sg_A == 1){
op_A = op_A - 0x80; // como es negativo, le quito el signo
op_A = -op_A; // cambio el signo en compl a 2
}
if (sg_B == 1) {
op_B = op_B + 1; // como es negativo, paso el compl a 1 a compl a 2
}
// ambos números están en compl a 2, los comparo con >
ROM[dir] = (op_A > op_B)? op_A : op_B;
}
}

