tics_tiempo = 0;
}
if (tics_tiempo >= 60SEG) {
estado = CEBAR;
out(CONTROL, OFFVCVA);
tics_tiempo = 0;
}
break;
case CIRCULAR:
deltaT = in(TEMP_OUT) – in(TEMP_IN);
if (deltaT < 30DECGRADO) {
estado = ESPERAR;
out(CONTROL, OFFVAVC);
tics_tiempo = 0;
}
if (!hay_caudal) {
estado = ARRANCAR;
out(CONTROL, OFFVCVA);
tics_tiempo = 0;
}
break;
case ESPERAR:
if (tics_tiempo >= 30MIN) {
estado = CEBAR;
out(CONTROL, OFFVCVA);
tics_tiempo = 0;
}
break;
}
}
}

