if (destino(codigos[3] == 1) vcontrol = vcontrol | INTERNACIONAL;
else vcontrol = vcontrol | NACIONAL;
if (codigos[2] == 0) {
out(LECTOR2, 0x01);
codigos[2] == in(LECTOR2);
}
out(LECTOR1, 0x01);
nuevo_codigo == in(LECTOR1);
