while(!(girado) && (tics > 0));
vcontrol = (vcontrol & NOTGIRAR) | CINTA;
out(CONTROL, vcontrol);

}
else {
vcontrol = vcontrol | CINTA;
out(CONTROL, vcontrol);
}
for(i = 3; i > 0; i--) codigos[i] = codigos[i – 1];
codigos[0] = nuevo_codigo;
}
