Solución Problema 1
a)
Cada dígito BCD ocupa 4 bits. Por lo tanto se tienen 16 bits de entrada (8 para numero 1 y 8 para
número 2). La suma no puede exceder 198 por lo que se precisan 8 bits de salida. Por lo tanto se
requiere una ROM de 64K x 8
Para armar la rom: con una ROM de 16Kx16 se arma RomA de 32Kx8
Luego con dos RomA se arma la rom de 64Kx8:
unsigned char ROM[65536];
void carga()
{
unsigned char a = 0, bcdA = 0;
do{
unsigned char b = 0, bcdB = 0;
do{
ROM[bcdA<<8 | bcdB] = a + b;
b++;
bcdB++;
if(bcdB & 0xF > 9)
bcdB += 6;
}while(b<100);
a++;
bcdA++;

if(bcdA & 0xF > 9)
bcdA += 6;
}while(a<100);
}
b)
carga proc
xor AH, AH ; AH=a
xor BH, BH ; BH=bcdA
loop1:
xor AL, AL ; AL=b
