Solución Problema 2
#define MAXPERSONAS 1000
#define CANT_CAM 128
#define 5_SEG 50
#define 10_SEG 100
#define 30_SEG 300
#define 60_SEG 600
#define ALARMA_CANTIDAD_DESACT 0
#define ALARMA_CANTIDAD_ACT 1
#define ALARMA_CANTIDAD_PAUSA 2
#define ALARMA_TEMP_DESACT 0
#define ALARMA_TEMP_ACT 1
$define TRUE 1
void interrupt isr_timer(){
tics++;
if (tics % 5_SEG == 0) OUT(PANTALLAS, cantidad);
if (alarma_cantidad == ALARMA_CANTIDAD_ACT){
if (tics_alarma_act == 0)
//activar alarma
OUT(ALARMA_MAX, 0x01);
tics_alarma_act++;
if (tics_alarma_act == 10_SEG){
alarma_cantidad = ALARMA_CANTIDAD_PAUSA;
tics_alarma_inact = 0;
tics_alarma_act = 0;
//desactivar alarma
OUT(ALARMA_MAX, 0x00);
}
}
if (alarma_cantidad == ALARMA_CANTIDAD_PAUSA){
tics_alarma_inact++;
if (tics_alarma_inact == 30_SEG){
if (cantidad > MAXPERSONAS){
alarma_cantidad = ALARMA_CANTIDAD_ACT;
tics_alarma_act++;
//activar alarma
OUT(ALARMA_MAX, 0x01);
}
else{
alarma_cantidad = ALARMA_CANTIDAD_DESACT;
}
}
}
if (alarma_temp_estado == ALARMA_TEMP_ACT){
int cont_alarmas_activas = 0;
for (int i=0; i < CANT_CAM; i++){
if (estado_cam[i]){
tics_cam[i]++;

if (tics_cam[i] == 60_SEG){
tics_cam[i] = 0;
estado_cam[i] = 0;
}
else{
cont_alarmas_activas++;
}
}
}
if (!cont_alarmas_activas)
alarma_temp_estado = ALARMA_TEMP_DESACT;
OUT(ALARMA_TEMP, 0x00);
}
}
void interrupt isr_contadores(){
int lectura_cont = IN(CONTADORES);
id_puerta = lectura_cont >> 6;
int cant = (lectura_cont & 0x3F) >> 1;
if (lectura_cont & 0x01)
cant = cant * (-1);
cantidad += cant;
if (cantidad > MAXPERSONAS) && alarma_cantidad != ALARMA_CANTIDAD_PAUSA)
alarma_cantidad = ALARMA_CANTIDAD_ACT;
}
void interrupt isr_camaras(){
char camaras_lect = IN(CAMARAS) >> 1;
if !(estado_cam[camaras_lect]){
estado_cam[camaras_lect] = 1;
tics_cam[camaras_lect] = 0;
//emito señal de alarma
OUT(ALARMA_TEMP, 0x01);
OUT(AVISAR_PUESTO, ( camaras_lect << 1) | 0x01);
alarma_temp_estado = ALARMA_TEMP_ACT;
}
}
int tics, tics_alarma_act, tics_alarma_inact, cantidad, alarma_temp_estado;
int tics_cam[CANT_CAM], estado_cam[CANT_CAM];
void main(){
// instalar ISRs
tics = 0;
tics_alarma_act = 0;
tics_alarma_inact = 0;
id_puerta = 0;
cantidad = 0;
for (int i = 0; i < CANT_CAM; i++) {
estado_cam[i] = 0;

tics_cam[i] = 0;
}
enable();
while (TRUE);
}

Solución Problema 2
#define CERRAR 1
#define ABRIR 3
#define APAGAR 0
#define T_5_MIN 3000
#define T_30_MIN 18000
#define ESPERO 0
#define ABRIENDO 1
#define CERRANDO 2
#define EMERGENCIA_CERRAR 3
void interrupt potencia_solicitada()
{
objetivo = in(POTENCIA) & 0x3F;
int sensor = in(TURBINA) & 0x3F;
char apagar = 0;
if(objetivo > sensor)
{
if(estado == CERRANDO)apagar = 1;
estado = ABRIENDO;
}
else if(objetivo < sensor)
{
if(estado == ABRIENDO)apagar = 1;
estado = CERRANDO;
}
else estado = ESPERO;
if(apagar && tics == 0)
{
out(COMPUERTA, APAGAR);
tics = T_5_MIN;
}
}
void interrupt tiempo()
{
if(tics > 0)
tics--;
}
void interrupt emergencia()
{
estado = EMERGENCIA_CERRAR;
}
void interrupt tope()
{
if(estado != ABRIENDO)
cerrada = true;
}
int estado;
int tics;
char cerrada;
int objetivo;

void main()
{
// instalar ISRs
tics = 0;
estado = ESPERO;
cerrada = false;
enable();
while(true)
{
switch(estado)
{
case ESPERO: break;
case ABRIENDO:
if(tics == 0)
{
if(in(TURBINA) & 0x3F >= objetivo)
{
out(COMPUERTA, APAGAR);
tics = T_5_MIN;
estado = ESPERO;
}else
{
out(COMPUERTA, ABRIR);
cerrada = false;
}
}
break;
case CERRANDO:
if(tics == 0)
{
if(in(TURBINA) & 0x3F <= objetivo || cerrada)
{
out(COMPUERTA, APAGAR);
tics = T_5_MIN;
estado = ESPERO;
}else out(COMPUERTA, CERRAR);
}
break;
case EMERGENCIA_CERRAR:
if(tics == 0 || cerrada)
{
if(!cerrada)
{
cerrada = false;
while(!cerrada)out(COMPUERTA, CERRAR);
}
out(COMPUERTA, APAGAR);
tics = T_30_MIN;
estado = espero;
while(tics > 0) {}
}
break;
}
}
}
